// Matches http:// or https:// followed by non-whitespace characters.
// The leading protocol is anchored so that misspelled schemes (e.g. htp://),
// other schemes (ftp://, mailto:, file://, javascript:, data:) and schemeless
// strings (example.com/path) are never matched.
const URL_REGEX = /https?:\/\/[^\s]+/g;

const ANCHOR_CLASS_NAME =
  "text-blue-600 underline break-all hover:text-blue-800";

// Strips trailing punctuation that is adjacent to, but not part of, the URL
// (e.g. a trailing period/comma, or an enclosing ")"/"]"). Returns the cleaned
// URL alongside the trailing characters that were removed so they can be
// rendered as plain text.
const splitTrailingPunctuation = (raw: string): [string, string] => {
  let url = raw;
  let trailing = "";

  let changed = true;
  while (changed && url.length > 0) {
    changed = false;
    const last = url[url.length - 1];

    if (".,;:!?".includes(last)) {
      trailing = last + trailing;
      url = url.slice(0, -1);
      changed = true;
    } else if (last === ")" || last === "]") {
      const open = last === ")" ? "(" : "[";
      const opens = url.split(open).length - 1;
      const closes = url.split(last).length - 1;
      if (closes > opens) {
        trailing = last + trailing;
        url = url.slice(0, -1);
        changed = true;
      }
    }
  }

  return [url, trailing];
};

const handleClick = (event: React.MouseEvent<HTMLAnchorElement>) => {
  event.stopPropagation();
};

const linkifyString = (text: string): React.ReactNode[] => {
  const nodes: React.ReactNode[] = [];
  let lastIndex = 0;
  let key = 0;

  for (const match of text.matchAll(URL_REGEX)) {
    const raw = match[0];
    const start = match.index ?? 0;
    const [url, trailing] = splitTrailingPunctuation(raw);

    if (start > lastIndex) {
      nodes.push(text.slice(lastIndex, start));
    }

    nodes.push(
      <a
        key={`link-${key++}`}
        href={url}
        target="_blank"
        rel="noopener noreferrer"
        className={ANCHOR_CLASS_NAME}
        onClick={handleClick}
      >
        {url}
      </a>,
    );

    if (trailing) {
      nodes.push(trailing);
    }

    lastIndex = start + raw.length;
  }

  if (lastIndex < text.length) {
    nodes.push(text.slice(lastIndex));
  }

  return nodes;
};

const LinkifyText = ({ children }: { children?: React.ReactNode }) => {
  // Only string children are scanned for URLs. null/undefined render as empty
  // content and numbers (or any other React node) are rendered as-is. Rendering
  // through a fragment keeps text as text nodes (React escapes them, so script
  // tags are never injected) and avoids adding a wrapper element.
  if (typeof children === "string") {
    return <>{linkifyString(children)}</>;
  }

  return <>{children}</>;
};

export default LinkifyText;
